import React from 'react';
import './HorizontalCard.css';

const HorizontalCard = ({ image, title, description, projectUrl, githubUrl, githubIcon }) => {
  return (
    <div className="hcard">
      <img className="hcard-image" src={image} alt={title} />
      <div className="hcard-content">
        <h3 className="hcard-title">{title}</h3>
        <p className="hcard-description">{description}</p>
      </div>
    </div>
  );
};

export default HorizontalCard;
